class ConsoleLineDto(BaseModel):
    """
        One console history entry, ready for the UI. Two kinds:
          • `line`   - ordinary console output from a stream.
          • `marker` - a lifecycle event (start/stop/update) surfaced inline
            so the console visually separates runs. int? ConsoleLineDto.State carries
            the ApplicationState for state markers; bool? ConsoleLineDto.Success the
            outcome for update-complete markers (with State null).
        long ConsoleLineDto.Seq is a per-shard monotonic sequence assigned by the
    server-side history buffer - clients use it to merge the REST history
    snapshot with the live SignalR feed without duplicates.
    """

    model_config = ConfigDict(
        populate_by_name=True,
    )
    stream_id: Annotated[str, Field(alias='streamId')]
    """
    Identifier of the source stream this line came from
    """
    text: str
    """
    The line text (English fallback for localised markers)
    """
    timestamp: AwareDatetime
    """
    When the line was produced
    """
    seq: int | constr(pattern=r'^-?(?:0|[1-9]\d*)$') | None = 0
    """
    Per-shard monotonic sequence used to merge history with the live feed
    """
    kind: str | None = 'line'
    """
    `line` for ordinary output, `marker` for an inline lifecycle event, `notice` for a notice, `error` for a failure reported on the shard, or `info` for an information line whose Text is its title
    """
    state: int | None = None
    """
    ApplicationState carried by a state marker; null otherwise
    """
    success: bool | None = None
    """
    Outcome carried by an update-complete marker; null otherwise
    """
    code: str | None = None
    """
    i18n key for an AMP-authored marker message; null for app output or uncatalogued lines
    """
    params: dict[str, Any] | None = None
    """
    Parameters for the localised Code message; null when there are none
    """
    level: str | None = None
    """
    Structured log level parsed from the console format regex; null when unmatched or unconfigured
    """
    origin: str | None = None
    """
    Structured origin/source field parsed from the console format regex; null when unmatched
    """


class ConsoleSpec(BaseModel):
    """
    Parsed from the Console.* keys in a .kvp file.
    Describes how AMP reads and interprets the application's console output.
    """

    model_config = ConfigDict(
        populate_by_name=True,
    )
    filter_match_regex: Annotated[str | None, Field(alias='filterMatchRegex')] = None
    """
    Regex to strip ANSI escape codes / noise from raw output
    """
    filter_match_replacement: Annotated[
        str | None, Field(alias='filterMatchReplacement')
    ] = None
    """
    Replacement text substituted for each string ConsoleSpec.FilterMatchRegex match
    """
    throwaway_message_regex: Annotated[
        str | None, Field(alias='throwawayMessageRegex')
    ] = None
    """
    Lines matching this are discarded entirely before storage
    """
    app_ready_regex: Annotated[str | None, Field(alias='appReadyRegex')] = None
    """
    When this matches, the app is considered Ready
    """
    server_auth_url_prompt_regex: Annotated[
        str | None, Field(alias='serverAuthURLPromptRegex')
    ] = None
    """
    Server authentication URL prompt (e.g. Hytale's OAuth device flow): when this
    matches a console line, the shard enters AwaitingUserAction and surfaces the URL
    the operator must visit. If the regex has a `url` named group, that's the URL;
    otherwise the whole match is used.
    """
    server_auth_ack_regex: Annotated[str | None, Field(alias='serverAuthAckRegex')] = (
        None
    )
    """
    Acknowledgement that server authentication completed - clears the prompt
    """
    user_join_regex: Annotated[str | None, Field(alias='userJoinRegex')] = None
    """
    Matches a console line announcing a user connecting. Named groups: `username`
    (required), `userid`, `sessionid`, and `endpoint` (or `ip`) for the address.
    """
    user_id_kind: Annotated[str | None, Field(alias='userIdKind')] = None
    """
    What kind of id the `userid` group captures (see UserIdKinds), which
    decides whether one person is recognised across servers. Empty means undeclared: a SteamID is
    still recognised by its shape, and anything else is only compared between shards of this
    template. Declare it when the id is global, and make it specific (`minecraft-uuid`).
    """
    user_leave_regex: Annotated[str | None, Field(alias='userLeaveRegex')] = None
    """
    Matches a console line announcing a user disconnecting
    """
    user_chat_regex: Annotated[str | None, Field(alias='userChatRegex')] = None
    """
    Matches a chat message line; typically captures the user and message text
    """
    pre_connect_regex: Annotated[str | None, Field(alias='preConnectRegex')] = None
    """
    For games that announce a connecting player across multiple lines.
    Fires before ConnectIPRegex; must capture an `id` group that
    correlates with either the `id` group in ConnectIPRegex or the
    `username`/`userid` in UserJoinRegex. An optional `userid`
    group supplies the user's id when the join line has none, matched up by
    the name in `id`: Minecraft's "UUID of player Steve is ..." line.
    """
    connect_ip_regex: Annotated[str | None, Field(alias='connectIPRegex')] = None
    """
    Captures the joining player's IP when it does not appear on the same
    line as UserJoinRegex.  Must include an `ip` capture group.
    Optional `id` group ties this line to a specific player (or
    PreConnect entry); without it, the IP is assigned to the most-recently
    announced pre-connect entry.
    """
    update_available_regex: Annotated[
        str | None, Field(alias='updateAvailableRegex')
    ] = None
    """
    When this matches, the app is signalling that an update is available
    """
    metrics_regex: Annotated[str | None, Field(alias='metricsRegex')] = None
    """
    Matches console lines carrying performance metrics to be parsed and recorded
    """
    download_progress_regex: Annotated[
        str | None, Field(alias='downloadProgressRegex')
    ] = None
    """
    Matches download-progress output lines during an update (e.g. progress bars from
    a custom downloader). Named capture groups: `percent` (required),
    `progressValue` + `progressUnits` and `totalValue` +
    `totalUnits` (optional, used to compute transfer speed). When this matches,
    the line is consumed as a structured progress event and not published to the
    console stream (keeps the transcript clean).
    """
    startup_progress_regex: Annotated[
        str | None, Field(alias='startupProgressRegex')
    ] = None
    """
                 Matches console lines reporting how far through STARTING the application is, for apps whose
                 startup is slow but measurable (Minecraft's "Preparing spawn area: 45%", world generation, big
                 modded packs). Named capture groups: `PercentageComplete` (required, the percentage), and
                 `stage` (optional, what it is doing - shown beside the bar).

                 The line is NOT consumed: unlike a download progress bar, which redraws hundreds of times and
    would drown the transcript, a startup progress line is part of the server's own startup log and
    users expect to see it. Progress is reported live only and never persisted - it is meaningless
    the moment the app is up, and writing every tick to KV would be pure amplification.
    """
    log_regex: Annotated[str | None, Field(alias='logRegex')] = None
    """
    Regex that matches structured log lines emitted by the application.
    Standard named capture groups: `origin`, `level`, `message`.
    Any group may be omitted if the log format does not provide it.
    The input timestamp, if present in the raw line, should be consumed by
    the regex but not captured - AMP always records its own UTC receive time.
    """
    suppress_log_at_start: Annotated[bool | None, Field(alias='suppressLogAtStart')] = (
        None
    )
    """
    Suppress log output until this regex fires (reduces startup noise)
    """
    activate_log_regex: Annotated[str | None, Field(alias='activateLogRegex')] = None
    """
    When bool ConsoleSpec.SuppressLogAtStart is set, this regex re-enables log output once it fires
    """
    command_triggers: Annotated[
        dict[str, str] | None, Field(alias='commandTriggers')
    ] = None
    """
    Automation rules (AMP 2 `App.CommandTriggers`): a console-line REGEX → a COMMAND
    to send back to the app when it matches. The command is template-expanded
    (`{{Setting}}`/`{{$PortRef}}`) and then has the match's capture groups
    substituted - `{{0}}` = whole match, `{{1}}`… = numbered groups,
    `{{name}}` = named groups. A command may carry embedded newlines to send several
    commands. (Hytale uses these to drive its `/auth login device` flow.)
    """


