class DeployedShard(BaseModel):
    """
    A concrete deployment of an AppSpec - an application that can be
    started, stopped, and managed on a specific SpireDefinition.
    This is the AMP3 equivalent of what AMP2 called an "Instance".

    Durable, rarely-written record.
    KV key: `amp.tn.{tenant}.sr.{shardId}`
    """

    model_config = ConfigDict(
        populate_by_name=True,
    )
    id: UUID | None = None
    tenant_id: Annotated[str | None, Field(alias='tenantId')] = None
    display_name: Annotated[str | None, Field(alias='displayName')] = None
    """
    User-chosen display name, e.g. "My Minecraft Server".
    Mutable - the friendly label shown in the UI.
    """
    description: str | None = None
    """
    Optional human-readable description of what this shard is for.
    Shown on the shard detail page and in listings.
    """
    name: str | None = None
    """
    Immutable, unique-per-tenant machine name. Used in log paths, NATS
    subject tokens, and anywhere a stable identifier is needed.
    Set once at creation, never changed. Must be NATS-subject-safe
    (lowercase alphanumeric + hyphen/underscore only).
    """
    template_slug: Annotated[str | None, Field(alias='templateSlug')] = None
    """
    The template this shard was created from, e.g. `"minecraft"`.
    Links to an AppSpec in the template catalogue.
    """
    display_image_source: Annotated[str | None, Field(alias='displayImageSource')] = (
        None
    )
    """
    The template's Meta.DisplayImageSource ("steam:appid" / "url:…" /
    "internal:name"), copied at creation and refreshed on update.
    Denormalized so listings render artwork from the shard record alone -
    never gated on the (potentially slow) template-catalogue load.
    """
    spire_id: Annotated[UUID | None, Field(alias='spireId')] = None
    """
    The spire (machine) this shard is assigned to run on
    """
    datastore_id: Annotated[UUID | None, Field(alias='datastoreId')] = None
    """
    The spire datastore this shard's files live in (see SpireDatastore).
    Empty = use the spire's default datastore. The agent's working directory is
    `{datastore.Path}/{WorkingDirName}`, resolved by the backend at launch.
    """
    working_dir_name: Annotated[str | None, Field(alias='workingDirName')] = None
    """
                Leaf directory name for this shard's files inside its datastore, e.g.
                `"valheim-3f9a2b1c"`. Set once at creation and never changed. Unique
                per shard (it embeds the shard id) so deleting a shard and recreating one
                with the same display name can NEVER reuse the old data directory - a
                privacy/security guarantee, and it also stops two same-named live shards
                from fighting over one directory.
                Empty on shards created before this field existed → the launcher falls
    back to string DeployedShard.Name for them.
    """
    created_by_user_id: Annotated[str | None, Field(alias='createdByUserId')] = None
    created_at: Annotated[AwareDatetime | None, Field(alias='createdAt')] = None
    installed_at: Annotated[AwareDatetime | None, Field(alias='installedAt')] = None
    """
    When the application files were last successfully installed/updated
    """
    installed_version: Annotated[str | None, Field(alias='installedVersion')] = None
    """
    Version string as reported after the last successful update
    """
    start_after_update_task_id: Annotated[
        UUID | None, Field(alias='startAfterUpdateTaskId')
    ] = None
    """
    The update task whose success starts this shard: set when a shard is created with "Start now",
    which runs its first update straight away, and cleared when that update ends. Kept on the record
    so a panel restart while the update runs still starts the shard when it finishes. Null when no
    start is waiting.
    """
    tags: list[str] | None = None
    """
    User-defined labels for grouping and filtering in the UI
    """
    suspended: bool | None = None
    """
    When true, the shard will not be started even if commanded to.
    Used for administrative holds - maintenance, billing suspension, etc.
    """
    disk_warning_acked: Annotated[bool | None, Field(alias='diskWarningAcked')] = None
    """
    The operator has acknowledged this shard's disk-usage warning, so the dismissible
    notice stays hidden. Cleared automatically by the usage scan once the shard drops
    back under the warning threshold, so the next approach to the limit is announced
    afresh rather than silently. Only the first, advisory level can be acknowledged at
    all - see bool DiskLimitPolicy.IsDismissible(DiskLimitLevel level).
    """
    deleted: bool | None = None
    """
    Soft-delete flag. Deleted shards are hidden from normal listings but
    their data is retained so the action can be undone immediately.
    Hard deletion is a separate, scheduled, operator-level operation.
    """
    deleted_at: Annotated[AwareDatetime | None, Field(alias='deletedAt')] = None
    """
    When the shard was soft-deleted, if applicable
    """


