class JavaRuntime(BaseModel):
    """
                 A Java runtime found installed on a spire host.

                 Deliberately structured rather than pre-formatted: AMP 2 built display strings like
    "TEMURIN 21 (hotspot) [System Default]" inside the scan, which cannot be translated. Here the
    scan reports facts and the UI composes the label, so "System default" can be localised.
    """

    model_config = ConfigDict(
        populate_by_name=True,
    )
    path: str | None = None
    """
    Absolute path to the java executable. This is the value a setting stores
    """
    major_version: Annotated[int | None, Field(alias='majorVersion')] = None
    """
    Major version (21, 17, 8). Zero when the directory name did not identify one
    """
    vendor: str | None = None
    """
    Distribution: "Adoptium", "Oracle", "Zulu", "Corretto", "GraalVM", "OpenJDK". Empty when the
    install gives nothing to identify it by.
    """
    kind: str | None = None
    """
    "JDK" or "JRE" - kept as initialisms, never title-cased. Empty when unknown
    """
    name: str | None = None
    """
    The install directory's own name, used as a label when nothing else was recognised
    """
    is_default: Annotated[bool | None, Field(alias='isDefault')] = None
    """
    This is the java on PATH - the one the host would use by default
    """
    is_system_default: Annotated[bool | None, Field(alias='isSystemDefault')] = None
    """
    Not a fixed install but "whatever java the host resolves at launch". Its string JavaRuntime.Path is
    a `$PATH`-prefixed token the agent resolves each time, so the shard follows the host's
    default instead of pinning today's answer.
    """


