class LicenceDto(BaseModel):
    """
    One activated licence and its current state
    """

    model_config = ConfigDict(
        populate_by_name=True,
    )
    spire_id: Annotated[UUID, Field(alias='spireId')]
    """
    The spire holding the licence's activation file; with the grade, the handle for removal
    """
    spire_name: Annotated[str, Field(alias='spireName')]
    """
    That spire's display name
    """
    grade_id: Annotated[UUID, Field(alias='gradeId')]
    """
    The edition's stable grade identifier
    """
    product_name: Annotated[str, Field(alias='productName')]
    """
    The licensed product, e.g. AMP
    """
    grade_name: Annotated[str, Field(alias='gradeName')]
    """
    The grade, e.g. Enterprise. Present it with the product as
        "{product} {grade} Edition" - never show the grade on its own
    """
    state: str
    """
    What the activation file says on its own: Valid, Expired, or Invalid (unreadable/moved-machine activation);
        or Unconfirmed while its spire cannot identify its machine (typically a start that ran ahead of the network) and is
        checking again. An Unconfirmed licence stands as it did when that spire last confirmed it since it started, and stands Invalid when it has not
    """
    standing: str
    """
    What counts: the file and the licensing service's last verdict together.
        Active, Grace, Lapsed, Revoked, Disabled, Unrecognised, OutOfTouch, Invalid or TermsRequired; only Active and Grace grant capacity
    """
    expires: AwareDatetime | None
    """
    When the licence lapses; null means lifetime
    """
    grace_ends: Annotated[AwareDatetime | None, Field(alias='graceEnds')]
    """
    When a licence in its grace period stops counting; for an Unconfirmed licence that counts,
        when it stops counting if it is never confirmed
    """
    usage: int
    """
    Installations that have activated this key, as last reported by the
        licensing service. Only an online query knows this, so a licence read back from its stored
        activation reports 0
    """
    limit_known: Annotated[bool, Field(alias='limitKnown')]
    """
    The licensing service has told this installation the key's limit
    """
    shard_limit: Annotated[int, Field(alias='shardLimit')]
    """
    The key's limit, shared by every installation using it; null means unlimited (or not known yet)
    """
    key_shards_total: Annotated[int, Field(alias='keyShardsTotal')]
    """
    Shards across every installation using this key, as of the last report
    """
    issued_at: Annotated[AwareDatetime | None, Field(alias='issuedAt')]
    """
    When the licence was created, when the licensing service has said
    """
    terms_version: Annotated[int, Field(alias='termsVersion')]
    """
    The licence terms the key is held under, when the service has said
    """
    required_terms_version: Annotated[int, Field(alias='requiredTermsVersion')]
    """
    The terms AMP 3 requires. A key below it stands TermsRequired until its holder accepts them
    """


