class SettingSpec(BaseModel):
    """
    One configurable setting exposed for an application: where its value comes from and goes
    (command line and/or config file), how it is validated, and how it is presented in the UI.
    """

    model_config = ConfigDict(
        populate_by_name=True,
    )
    field_name: Annotated[str | None, Field(alias='fieldName')] = None
    """
    The setting's identifier, used as its config/command-line key unless string SettingSpec.ParamFieldName overrides it
    """
    param_field_name: Annotated[str | None, Field(alias='paramFieldName')] = None
    """
    Optional alternate key to emit on disk / on the command line instead of string SettingSpec.FieldName
    """
    effective_key: Annotated[str | None, Field(alias='effectiveKey')] = None
    """
    The setting's on-disk / on-command-line key: string SettingSpec.ParamFieldName
    when set, otherwise string SettingSpec.FieldName. The single definition used by
    config-file generation, template substitution, and command-line building so
    the key never derives differently across them.
    """
    required: bool | None = None
    """
    The user must provide a value for this setting
    """
    hidden: bool | None = None
    """
    The setting is not shown in the UI (still applied from its default/stored value)
    """
    platform: HostPlatform | None = None
    """
    Host platforms this setting applies to; mirrors a stage's UpdateSourcePlatform
    """
    deployment: SettingDeployment | None = None
    """
    Whether this setting applies to containerised shards, native ones, or both
    """
    condition_setting: Annotated[str | None, Field(alias='conditionSetting')] = None
    """
    Setting key that gates this one; shown only when its value matches string SettingSpec.ConditionValue. Mirrors a stage's UpdateSourceConditionSetting
    """
    condition_value: Annotated[str | None, Field(alias='conditionValue')] = None
    """
    Value that string SettingSpec.ConditionSetting must equal for this setting to be shown
    """
    default_value: Annotated[str | None, Field(alias='defaultValue')] = None
    """
    Value used when the user has not set one. Null when the template declares none, which is
    distinct from an empty default: a setting with no default and no value is left out of a
    generated config file, so the application applies its own default.
    """
    meta: str | None = None
    """
    Free-form metadata carried through from the manifest
    """
    category: str | None = None
    """
    Top-level grouping used to organise the settings UI
    """
    subcategory: str | None = None
    """
    Secondary grouping within string SettingSpec.Category
    """
    special: str | None = None
    """
    Special handling marker (e.g. "array:text", "array:number", "listfile", "fileexists") that changes how the value is written
    """
    display_name: Annotated[str | None, Field(alias='displayName')] = None
    """
    Label shown for this setting in the UI
    """
    description: str | None = None
    """
    Help text explaining what the setting does
    """
    keywords: str | None = None
    """
    Extra search terms that help users find this setting
    """
    input_type: Annotated[str | None, Field(alias='inputType')] = None
    """
    The input control to render (e.g. text, number, checkbox, enum)
    """
    is_secret: Annotated[bool | None, Field(alias='isSecret')] = None
    """
    The value is a secret (token, API key, connection string, ...). Secret values are masked
    on read and never returned to the client in the clear, independent of string SettingSpec.InputType.
    A `password` input is treated as secret automatically; set this for secret-bearing
    settings that render as plain text.
    """
    placeholder: str | None = None
    """
    Placeholder text shown in an empty input field
    """
    suffix: str | None = None
    """
    Unit or suffix shown after the input (e.g. "MB", "seconds")
    """
    order: int | None = None
    """
    Sort order within its category; lower values appear first
    """
    read_only: Annotated[bool | None, Field(alias='readOnly')] = None
    """
    Displayed but not editable (platform settings manifest)
    """
    is_flag_argument: Annotated[bool | None, Field(alias='isFlagArgument')] = None
    """
    The setting is a presence flag: it emits string SettingSpec.FlagValue when enabled rather than a key/value pair
    """
    flag_value: Annotated[str | None, Field(alias='flagValue')] = None
    """
    The literal text emitted on the command line when bool SettingSpec.IsFlagArgument is set and enabled
    """
    include_in_command_line: Annotated[
        bool | None, Field(alias='includeInCommandLine')
    ] = None
    """
    Include this setting when building the command line
    """
    include_in_config_file: Annotated[
        bool | None, Field(alias='includeInConfigFile')
    ] = None
    """
    Include this setting when generating config files
    """
    skip_if_empty: Annotated[bool | None, Field(alias='skipIfEmpty')] = None
    """
    Omit this setting entirely when its value is empty
    """
    enum_values: Annotated[dict[str, str] | None, Field(alias='enumValues')] = None
    """
    Allowed values for an enum-style setting: stored value → display label
    """
    value_source_id: Annotated[str | None, Field(alias='valueSourceId')] = None
    """
                 Id of the VersionSource this setting's options come from, for a value list
                 that is read from an upstream manifest rather than fixed in the template.

                 The list is NOT delivered with the settings payload: the client asks for it when the
    control is actually opened. A page carrying a dozen version pickers would otherwise fan out
    a dozen upstream fetches nobody asked for. So a setting with this set arrives with its
    current value and this id, and nothing else.
    """
    min_value: Annotated[
        float | constr(pattern=r'^-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?$') | None,
        Field(alias='minValue'),
    ] = None
    """
    Minimum allowed numeric value; null means no lower bound
    """
    max_value: Annotated[
        float | constr(pattern=r'^-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?$') | None,
        Field(alias='maxValue'),
    ] = None
    """
    Maximum allowed numeric value; null means no upper bound. See bool SettingSpec.IsHostCap
    """
    is_host_cap: Annotated[bool | None, Field(alias='isHostCap')] = None
    """
    True when MaxValue was imposed by the host's infra cap (e.g. MaxUsersCap), not by the
    application manifest. The UI uses this to show "Capped at X by the host" vs. a plain
    valid-range hint when the manifest just declares the setting's natural bounds.
    """
    multiplier: (
        float | constr(pattern=r'^-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?$') | None
    ) = None
    """
    NOT IMPLEMENTED - parsed from the manifest and currently read by nothing.
    In AMP 2 this scales the STORED value on its way OUT to the config file / command line
    (store minutes, emit milliseconds); the UI never sees it. Implementing it means applying
    it in `ctx.ResolveFieldValue` AND inverting it in `ConfigFileImporter` - it is
    the one attribute that makes the write path non-idempotent, so without the divide, every
    import of a merged config file would inflate the value by the multiplier again.
    """
    multiple_of: Annotated[
        float | constr(pattern=r'^-?(?:0|[1-9]\d*)(?:\.\d+)?(?:[eE][+-]?\d+)?$') | None,
        Field(alias='multipleOf'),
    ] = None
    """
    The value should be a multiple of this number. Currently only drives the number input's
    `step` attribute in the UI - AMP 2 additionally rounds to the nearest multiple when
    writing, and uses whether this is an integer or a float to decide the JSON node's type.
    """
    max_length: Annotated[int | None, Field(alias='maxLength')] = None
    """
    Maximum string length; -1 means unlimited
    """
    list_value_prefix: Annotated[str | None, Field(alias='listValuePrefix')] = None
    """
    Text prepended to each item when writing a list-valued setting
    """
    list_value_separator: Annotated[str | None, Field(alias='listValueSeparator')] = (
        None
    )
    """
    Separator placed between items when writing a list-valued setting
    """
    exclude_from_import: Annotated[bool | None, Field(alias='excludeFromImport')] = None
    """
    Do not import a value for this setting when importing an existing installation
    """


