class ShardDiskUsage(BaseModel):
    """
    Disk usage of one directory inside a datastore. DiskUsageKind ShardDiskUsage.Kind says which case it is:
      • Active shard - DiskUsageKind.Shard, bool ShardDiskUsage.Deleted false.
      • Soft-deleted shard - DiskUsageKind.Shard, bool ShardDiskUsage.Deleted true
        (the operator can Restore it or Delete it permanently).
      • Orphan - DiskUsageKind.Orphan: data with no matching shard at all
        (surface it, never silently omit).
      • Backups - DiskUsageKind.Backups: every shard's snapshot archives.
    """

    model_config = ConfigDict(
        populate_by_name=True,
    )
    kind: DiskUsageKind | None = None
    """
    What this directory is; only DiskUsageKind.Orphan rows may be purged as orphans
    """
    shard_id: Annotated[UUID | None, Field(alias='shardId')] = None
    """
    Matched shard id; Guid Guid.Empty unless DiskUsageKind ShardDiskUsage.Kind is DiskUsageKind.Shard
    """
    name: str | None = None
    """
    Directory name under the datastore (matches DeployedShard.WorkingDirName, or Name on legacy shards)
    """
    size_mb: Annotated[
        int | constr(pattern=r'^-?(?:0|[1-9]\d*)$') | None, Field(alias='sizeMb')
    ] = None
    """
    Size of this directory on disk, in megabytes
    """
    deleted: bool | None = None
    """
    True when this directory belongs to a soft-deleted shard (restorable / purgeable)
    """
    deleted_at: Annotated[AwareDatetime | None, Field(alias='deletedAt')] = None
    """
    When the shard was soft-deleted (drives retention purge); null unless bool ShardDiskUsage.Deleted
    """
    display_name: Annotated[str | None, Field(alias='displayName')] = None
    """
    Display name of the matched shard (active or deleted); empty for true orphans
    """
    limit_mb: Annotated[
        int | constr(pattern=r'^-?(?:0|[1-9]\d*)$') | None, Field(alias='limitMb')
    ] = None
    """
    The shard's configured disk budget in MB at scan time, copied here so a reader of the
    report can judge long ShardDiskUsage.SizeMb without fetching every shard's infra settings.
    0 = no limit (always the case for orphans, which belong to no shard).
    """
    limit_level: Annotated[DiskLimitLevel | None, Field(alias='limitLevel')] = None
    """
    Where long ShardDiskUsage.SizeMb stood against long ShardDiskUsage.LimitMb when this scan ran.
    Evaluated on the spire that owns the files, at the moment they were measured, so every
    reader - UI banner, start guard, enforcement - agrees on one verdict instead of each
    recomputing it from numbers of differing freshness.
    """


class ShardEndpointAddress(BaseModel):
    """
    One resolved way to reach a shard's port, with everything the UI needs to present it honestly:
    the address itself, where it came from, and what is known to be in the way.
    """

    model_config = ConfigDict(
        populate_by_name=True,
    )
    reach: EndpointReach
    """
    Whether this is the outside-world address or the same-network one
    """
    host: str
    """
    Hostname or IP to dial
    """
    port: int
    """
    Port to dial; meaningless when ShowPort is false
    """
    show_port: Annotated[bool, Field(alias='showPort')]
    """
    False only when the operator advertised a bare host and said it carries no port (a reverse proxy
    or an SRV record routes it), in which case appending one would send people to the wrong place.
    """
