class ShardSnapshotSettings(BaseModel):
    """
    Per-shard guardrails for snapshot storage. Both limits are evaluated pre-flight
    against the <b>uncompressed</b> (0-compression) size estimate so a snapshot is
    refused with a visible reason before any zipping work happens. 0 = no limit.
    Cadence/retention ("cycling") is deliberately out of scope until the scheduler.
    """

    model_config = ConfigDict(
        populate_by_name=True,
    )
    max_backup_size_mb: Annotated[
        int | constr(pattern=r'^-?(?:0|[1-9]\d*)$') | None,
        Field(alias='maxBackupSizeMb'),
    ] = None
    """
    Maximum uncompressed size of a single snapshot, MB. 0 = no limit
    """
    max_total_storage_mb: Annotated[
        int | constr(pattern=r'^-?(?:0|[1-9]\d*)$') | None,
        Field(alias='maxTotalStorageMb'),
    ] = None
    """
    Maximum aggregate snapshot storage for this shard, MB. 0 = no limit
    """
    stop_when_no_quiesce: Annotated[bool | None, Field(alias='stopWhenNoQuiesce')] = (
        None
    )
    """
    When the app declares no quiescence command, stop the shard for the duration of
    the snapshot (consistent capture) rather than snapshotting it hot. Default true.
    """


class ShardState(BaseModel):
    model_config = ConfigDict(
        populate_by_name=True,
    )
    shard_id: Annotated[UUID | None, Field(alias='shardId')] = None
    tenant_id: Annotated[str | None, Field(alias='tenantId')] = None
    status: ApplicationState | None = None
    revision: int | constr(pattern=r'^-?(?:0|[1-9]\d*)$') | None = None
    """
    The KV revision this copy of the record was read at, which orders any two copies a reader
    holds: a copy with a lower revision is older. Set by the reads that reach a browser (the
    state feed's push, the REST state read) from the entry they read. Only the entry's revision
    counts: a value left inside the JSON by an earlier read that was written back is meaningless,
    and no writer of the record reads it.
    """
    metrics: MetricsModel | None = None
    last_heartbeat: Annotated[AwareDatetime | None, Field(alias='lastHeartbeat')] = None
    active_task_id: Annotated[UUID | None, Field(alias='activeTaskId')] = None
    """
    If a ManagedTask is currently running against this shard, its ID
    """
    process_id: Annotated[int | None, Field(alias='processId')] = None
    """
    OS process ID of the running application. Null when stopped
    """
    running_version: Annotated[str | None, Field(alias='runningVersion')] = None
    """
    Version reported by the running process, if available
    """
    agent_version: Annotated[str | None, Field(alias='agentVersion')] = None
    """
    Build version of the shard AGENT supervising this shard (distinct from
    string? ShardState.RunningVersion, which is the hosted app's version). Persisted from the agent's
    handshake/heartbeat so the spire knows which agent binary each live shard runs on - the
    input to stale-agent restart escalation and version GC. Null until an agent reports in.
    """
    last_error_message: Annotated[str | None, Field(alias='lastErrorMessage')] = None
    """
    Set when the shard transitions to a failed state (English fallback)
    """
    last_error_code: Annotated[str | None, Field(alias='lastErrorCode')] = None
    """
    Optional i18n key for string? ShardState.LastErrorMessage so the client can localise it
    """
    last_error_params: Annotated[
        dict[str, Any] | None, Field(alias='lastErrorParams')
    ] = None
    """
    Parameters for string? ShardState.LastErrorCode
    """
    status_message: Annotated[str | None, Field(alias='statusMessage')] = None
    """
    What the agent is doing WITHIN its current state, when it said. A state on its own is often too
    coarse to be reassuring: "Pre-Start" for a minute reads as hung, where "Connecting to the
    gateway spire" reads as working. Cleared by the next transition that carries no message, so it
    can never linger and describe something that finished. English fallback, like
    string? ShardState.LastErrorMessage.
    """
    status_code: Annotated[str | None, Field(alias='statusCode')] = None
    """
    Optional i18n key for string? ShardState.StatusMessage so the client can localise it
    """
    status_params: Annotated[dict[str, Any] | None, Field(alias='statusParams')] = None
    """
    Parameters for string? ShardState.StatusCode
    """
    started_at: Annotated[AwareDatetime | None, Field(alias='startedAt')] = None
    """
    When the application was last launched, from the agent's most recent Starting transition.
    Kept after the shard stops; null only for a shard that has never been started.
    """
    sleep: ShardSleepStatus | None = None
    is_running: Annotated[bool | None, Field(alias='isRunning')] = None
    is_stopped: Annotated[bool | None, Field(alias='isStopped')] = None
    awaits_licence: Annotated[bool | None, Field(alias='awaitsLicence')] = None
    """
    Waiting for a person to accept the application's licence before a start that no person was
    waiting on can go ahead. The shard is in the same AwaitingUserAction state an agent's own prompt
    puts it in, but no agent runs: the start was refused before anything was launched.
    """
    accepts_traffic: Annotated[bool | None, Field(alias='acceptsTraffic')] = None
    """
                 Whether anything on the far side will answer a connection, which is not the same question as
                 whether the application is running.

                 A sleeping shard has no application process at all, and yet its port must stay reachable: the
    whole point of sleep is that the agent holds the port, answers queries on the application's
    behalf and starts it again when somebody actually connects. Cutting off a sleeping shard's
    traffic removes the only thing that could ever wake it.
    """
    is_busy: Annotated[bool | None, Field(alias='isBusy')] = None


