class ApplicationLifecycle(BaseModel):
    """
    Defines how an application launches, is detected as ready, and shuts down:
    executable paths, command-line arguments, ready/exit behaviour, and quiescence.
    """

    model_config = ConfigDict(
        populate_by_name=True,
    )
    root_dir: Annotated[str | None, Field(alias='rootDir')] = None
    """
    Root directory the application is installed into, relative to the shard directory
    """
    base_directory: Annotated[str | None, Field(alias='baseDirectory')] = None
    """
    Base directory that config-file paths are resolved against
    """
    executable_win: Annotated[str | None, Field(alias='executableWin')] = None
    """
    Executable to launch on Windows
    """
    executable_linux: Annotated[str | None, Field(alias='executableLinux')] = None
    """
    Executable to launch on Linux
    """
    executable_container: Annotated[str | None, Field(alias='executableContainer')] = (
        None
    )
    """
    Executable to launch when the shard runs in a container AMP manages; empty means
    string ApplicationLifecycle.ExecutableLinux. Besides a path it may be `java:&lt;major&gt;`, which the
    agent resolves where it runs to the newest installed JDK of that major, so a template
    chooses a Java by version from whatever the image carries rather than by a host path the
    container does not have.
    """
    working_dir: Annotated[str | None, Field(alias='workingDir')] = None
    """
    Working directory to run the executable from; empty means the base directory
    """
    compatibility: CompatibilityModes | None = None
    """
    Console-buffering workarounds the app needs (App.Compatibility):
    apps that detect a pipe and switch to block-buffered output get a
    pseudo-terminal instead (ConPTY on Windows, socat pty on Linux).
    """
    linux_command_line_args: Annotated[
        str | None, Field(alias='linuxCommandLineArgs')
    ] = None
    """
    Extra command-line arguments applied only on Linux
    """
    windows_command_line_args: Annotated[
        str | None, Field(alias='windowsCommandLineArgs')
    ] = None
    """
    Extra command-line arguments applied only on Windows
    """
    command_line_args: Annotated[str | None, Field(alias='commandLineArgs')] = None
    """
    Base command-line arguments applied on all platforms
    """
    command_line_parameter_format: Annotated[
        str | None, Field(alias='commandLineParameterFormat')
    ] = None
    """
    Format string for each generated setting argument: {0}=key, {1}=value
    """
    command_line_parameter_delimiter: Annotated[
        str | None, Field(alias='commandLineParameterDelimiter')
    ] = None
    """
    Delimiter placed between generated command-line parameters
    """
    rapid_startup: Annotated[bool | None, Field(alias='rapidStartup')] = None
    """
    Skip the usual start-up delays and bring the app up as fast as possible
    """
    application_ready_mode: Annotated[
        ReadyIndicator | None, Field(alias='applicationReadyMode')
    ] = None
    """
    How AMP determines the app has finished starting
    """
    application_ready_timeout_seconds: Annotated[
        int | None, Field(alias='applicationReadyTimeoutSeconds')
    ] = None
    """
    Seconds before ReadyIndicator.Timeout mode declares the app ready (also the cap for other modes if you want a fallback)
    """
    monitor_child_process_name: Annotated[
        str | None, Field(alias='monitorChildProcessName')
    ] = None
    """
    A regex over a process's command line naming the real server when the executable AMP
    launches is only a launcher for it (Proton's script, a mod loader). Its template tokens
    are expanded with their values regex-escaped. Empty means the launched process is the
    server. When set, metrics, liveness, the exit code and the stop path follow the matching
    process with the most resident memory among the shard's own processes.
    """
    monitor_direct_child_only: Annotated[
        bool | None, Field(alias='monitorDirectChildOnly')
    ] = None
    """
    Only a descendant of the launched process may be the monitored server
    """
    supports_universal_sleep: Annotated[
        bool | None, Field(alias='supportsUniversalSleep')
    ] = None
    """
                 This application can be put to sleep: stopped while empty, with AMP holding its ports and
                 starting it again when someone tries to connect (AMP 2's App.SupportsUniversalSleep).

                 A capability claim about the app's clients: that they touch the declared port before they
    need a reply, and that they wait long enough for the real server to come up. False leaves
    sleep hidden entirely rather than offered and broken.
    """
    wakeup_mode: Annotated[SleepWakeupModes | None, Field(alias='wakeupMode')] = None
    """
    Which triggers may wake this shard from sleep
    """
    sleep_on_start: Annotated[bool | None, Field(alias='sleepOnStart')] = None
    """
    Put the shard straight to sleep once it has started and proved it can
    """
    sleep_delay_minutes: Annotated[int | None, Field(alias='sleepDelayMinutes')] = None
    """
    How many minutes the shard must be empty before it sleeps
    """
    sleep_doze_delay_minutes: Annotated[
        int | None, Field(alias='sleepDozeDelayMinutes')
    ] = None
    """
    How many minutes to wait before sleeping again when the shard was woken but nobody
    actually joined. Shorter than int ApplicationLifecycle.SleepDelayMinutes on purpose: a wake that came
    to nothing (a server browser refreshing, a port scan) should not hold the shard up for the
    full delay.
    """
    sleep_start_threshold_seconds: Annotated[
        int | None, Field(alias='sleepStartThresholdSeconds')
    ] = None
    """
                 The longest a cold start may take, in seconds, for sleep to be offered at all.

                 Waking is only invisible if the server accepts connections before the client that woke it
    gives up, and most give up around thirty seconds. So AMP times every start, and a shard
    that took longer than this is not offered sleep for that run - the alternative is a shard
    that sleeps and then cannot be reached, which is worse than one that never slept. The
    maintainer raises it only for titles whose clients are known to wait longer.
    """
    steam_update_anonymous_login: Annotated[
        SteamAnonymousLoginMode | None, Field(alias='steamUpdateAnonymousLogin')
    ] = None
    """
    Whether SteamCMD update stages can log in anonymously
    """
    exit_method: Annotated[ExitMethod | None, Field(alias='exitMethod')] = None
    """
    How to shut the app down (used on all platforms unless overridden by ExitMethod ApplicationLifecycle.ExitMethodWindows)
    """
    exit_method_windows: Annotated[
        ExitMethod | None, Field(alias='exitMethodWindows')
    ] = None
    """
    Windows-specific shutdown method; ExitMethod.None means use ExitMethod ApplicationLifecycle.ExitMethod
    """
    startup_authentication_required: Annotated[
        bool | None, Field(alias='startupAuthenticationRequired')
    ] = None
    """
    The app requires an authentication step during startup before it can run
    """
    exit_timeout: Annotated[int | None, Field(alias='exitTimeout')] = None
    """
    Seconds to wait for a graceful exit before force-killing the process
    """
    exit_string: Annotated[str | None, Field(alias='exitString')] = None
    """
    Command string sent to the console for ExitMethod.String shutdown
    """
    exit_file: Annotated[str | None, Field(alias='exitFile')] = None
    """
    File written for ExitMethod.WriteToFile shutdown
    """
    quiescence_command: Annotated[str | None, Field(alias='quiescenceCommand')] = None
    """
    Command that tells the app to flush state and pause (for consistent snapshots/backups).
    Several may be given, separated by `;` - Minecraft needs "save-off;save-all flush",
    since disabling writes and forcing the flush are two separate commands.
    """
    dequiescence_command: Annotated[str | None, Field(alias='dequiescenceCommand')] = (
        None
    )
    """
    Command that resumes the app after a quiescence; `;`-separated as above
    """
    quiesce_ack_regex: Annotated[str | None, Field(alias='quiesceAckRegex')] = None
    """
    Console line proving the flush finished - "Saved the game" and the like.
    """
    quiesce_settle_delay_milliseconds: Annotated[
        int | None, Field(alias='quiesceSettleDelayMilliseconds')
    ] = None
    """
    After issuing string ApplicationLifecycle.QuiescenceCommand, how long to wait before touching files.
    """


