class UpdateStage(BaseModel):
    """
    A single step in an application's install/update sequence: what action to run,
    its inputs and target, the platforms it applies to, and how failures are handled.
    Ported from the AMP 2 specification.
    """

    model_config = ConfigDict(
        populate_by_name=True,
    )
    update_source: Annotated[UpdateSteps | None, Field(alias='updateSource')] = None
    """
    The kind of step this stage performs - the runner dispatches on this
    """
    update_stage_name: Annotated[str | None, Field(alias='updateStageName')] = None
    """
    Short name for this stage, shown in progress output
    """
    update_stage_description: Annotated[
        str | None, Field(alias='updateStageDescription')
    ] = None
    """
    Longer description of what this stage does
    """
    update_source_platform: Annotated[
        HostPlatform | None, Field(alias='updateSourcePlatform')
    ] = None
    """
    Host platform(s) this stage runs on
    """
    update_source_arch: Annotated[
        HostArchitecture | None, Field(alias='updateSourceArch')
    ] = None
    """
    CPU architecture filter (AMP 2 semantics: stages run only on matching hosts; default All)
    """
    update_source_data: Annotated[str | None, Field(alias='updateSourceData')] = None
    """
    Where the update is coming from. Such as an URL, App ID, etc
    """
    update_source_args: Annotated[str | None, Field(alias='updateSourceArgs')] = None
    """
    Extra arguments passed to the step (e.g. command-line args for an executable)
    """
    update_source_version: Annotated[str | None, Field(alias='updateSourceVersion')] = (
        None
    )
    """
    Version or branch/tag to fetch, where the step supports it
    """
    update_source_extra: Annotated[str | None, Field(alias='updateSourceExtra')] = None
    """
    Additional step-specific data
    """
    update_source_target: Annotated[str | None, Field(alias='updateSourceTarget')] = (
        None
    )
    """
    Where the update data is being saved to
    """
    unzip_update_source: Annotated[bool | None, Field(alias='unzipUpdateSource')] = None
    """
    Extract the fetched source after downloading it
    """
    overwrite_existing_files: Annotated[
        bool | None, Field(alias='overwriteExistingFiles')
    ] = None
    """
    Overwrite files that already exist at the target
    """
    force_download_platform: Annotated[
        HostPlatform | None, Field(alias='forceDownloadPlatform')
    ] = None
    update_source_condition_setting: Annotated[
        str | None, Field(alias='updateSourceConditionSetting')
    ] = None
    """
    Setting key that gates this stage; the stage runs only when its value matches string UpdateStage.UpdateSourceConditionValue
    """
    update_source_condition_value: Annotated[
        str | None, Field(alias='updateSourceConditionValue')
    ] = None
    """
    Value that string UpdateStage.UpdateSourceConditionSetting must equal for this stage to run
    """
    delete_after_extract: Annotated[bool | None, Field(alias='deleteAfterExtract')] = (
        None
    )
    """
    Delete the downloaded archive after extracting it
    """
    run_in_background: Annotated[bool | None, Field(alias='runInBackground')] = None
    """
    Start this stage's process and move on: the process is a helper the application uses (a
    database server, a dedicated server launcher), its output keeps reaching the console, and it
    is ended with the application's run, or when the update finishes for an update stage
    """
    skip_on_failure: Annotated[bool | None, Field(alias='skipOnFailure')] = None
    """
    Continue the update sequence even if this stage fails
    """
    process_tool_output: Annotated[bool | None, Field(alias='processToolOutput')] = None
    """
    Pass the stage's output through the console's handlers. Always the case: every stage line goes
    through the template's console handlers whatever its value
    """
    one_shot: Annotated[bool | None, Field(alias='oneShot')] = None
    """
    Run this stage only once (on first install) rather than on every update
    """


class VersionSource(BaseModel):
    """
                 A list of installable versions read from an upstream manifest, so a template can offer a real
                 dropdown instead of asking the user to type a version string.

                 Each candidate carries three things: the string VersionSource.Value that gets stored, the
    string VersionSource.Display string the user picks from, and a bag of named Dictionary&lt;string, string&gt; VersionSource.Fields. The
    selected candidate's fields become {{Setting.field}} tokens usable anywhere a token
    already is - another source's URL, a download URL template, an update stage's arguments. That
    one rule is what lets a single mechanism cover every upstream, including the ones that need a
    second request to find the actual download.See docs/version-sources.md for the reasoning, including why a value the upstream
    already publishes whole (Forge's 1.20.1-47.2.0) is kept whole rather than split.
    """

    model_config = ConfigDict(
        populate_by_name=True,
    )
    id: str | None = None
    """
    Identifies this source; a setting names it to be fed from it
    """
    url: str | None = None
    """
    The single upstream document, for the common case. Ignored when List&lt;VersionSourceDocument&gt; VersionSource.Documents is set.
    """
    documents: list[VersionSourceDocument] | None = None
    """
    Several upstream documents merged into one list, in order
    """
    format: VersionSourceFormat | None = None
    """
    How the documents are encoded
    """
    select: str | None = None
    """
    Path selecting the candidate nodes (JSONPath or XPath per VersionSourceFormat VersionSource.Format)
    """
    value: str | None = None
    """
    Path WITHIN a candidate giving the stored value. Empty or `$` means the node itself.
    """
    display: str | None = None
    """
    Path within a candidate giving the display string. Empty falls back to the value.
    """
    fields: dict[str, str] | None = None
    """
    Extra named values pulled from each candidate, as `name -&gt; path within the candidate`.
    These become `{{Setting.name}}` tokens once a candidate is selected, which is how a
    second-hop URL (Mojang) or a download filename (Paper) reaches the update stage.
    """
    where: dict[str, str] | None = None
    """
    Values a candidate must carry to enter the list, as `field name -&gt; required value`
    over Dictionary&lt;string, string&gt; VersionSource.Fields. Applied as the list is read, so a candidate that fails it is
    never cached, never offered and never what string VersionSelection.Latest means:
    Mojang's manifest lists snapshots first, and the latest Vanilla Minecraft has to be the
    latest release. A candidate without the field does not match; values compare exactly.
    """
    url_template: Annotated[str | None, Field(alias='urlTemplate')] = None
    """
    Builds the download URL from a candidate. Tokens are `{value}`, `{display}` and
    any Dictionary&lt;string, string&gt; VersionSource.Fields name. The result is exposed as the reserved
    `downloadUrl` field, so an update stage is just
    `FetchURL` of `{{Setting.downloadUrl}}` and no new stage type is needed.
    """
    sort: VersionSortOrder | None = None
    """
    Ordering applied before the list is shown
    """
    cache_minutes: Annotated[int | None, Field(alias='cacheMinutes')] = None
    """
    How long a fetched list stays fresh for DISPLAY. Resolution tolerates any age.
    """
    depends_on: Annotated[list[str] | None, Field(alias='dependsOn')] = None
    """
    Settings whose values this source's URLs interpolate. Load-bearing in three places: it keys
    the cache, it invalidates this source when one of them changes, and it tells the UI which
    dependent dropdowns to clear. A source with dependencies is not evaluated until they all
    have values.
    """


class AppSpec(BaseModel):
    """
    The complete definition of a manageable application (a game server or app),
    parsed from a template's .kvp file. Everything AMP needs to install, configure,
    launch, monitor, and update a shard of this application.
    """

    model_config = ConfigDict(
        populate_by_name=True,
    )
    id: UUID | None = None
    """
    Stable unique identifier for this template definition
    """
    schema_version: Annotated[int | None, Field(alias='schemaVersion')] = None
    """
    Version of the AppSpec schema this document conforms to, for forward migration
    """
    template_slug: Annotated[str | None, Field(alias='templateSlug')] = None
    """
    The template slug as it appears in the repository (e.g. "ark-se", "minecraft").
    Derived from the .kvp filename. Stable across updates.
    """
    lifecycle: ApplicationLifecycle | None = None
    """
    How the application launches, becomes ready, and exits
    """
    management: ApplicationManagement | None = None
    """
    How AMP administers the running application (console, RCON, IP binding, capacity)
    """
    metadata: SpecMetadata | None = None
    """
    Descriptive and platform metadata (display name, OS/arch support, container policy, release state)
    """
    console: ConsoleSpec | None = None
    """
    How AMP reads and interprets the application's console output
    """
    port_references: Annotated[PortReferences | None, Field(alias='portReferences')] = (
        None
    )
    """
    Named port references used to resolve which port serves each role (admin, primary, sleep query)
    """
    update_stages: Annotated[list[UpdateStage] | None, Field(alias='updateStages')] = (
        None
    )
    """
    Ordered stages that install and update the application (SteamCMD, downloads, extraction, etc.)
    """
    pre_start_stages: Annotated[
        list[UpdateStage] | None, Field(alias='preStartStages')
    ] = None
    """
    Stages run on EVERY start, after PreStart and before the app
    launches (App.PreStartStages - same shape as update stages, e.g.
    Factorio creating its world save). Condition gating typically
    makes them one-time in practice.
    """
    port_requirements: Annotated[
        list[PortRequirement] | None, Field(alias='portRequirements')
    ] = None
    """
    Network ports the application needs, with their roles, protocols, and ranges
    """
    version_sources: Annotated[
        list[VersionSource] | None, Field(alias='versionSources')
    ] = None
    """
    Upstream manifests this app's installable versions are read from, so version settings can be
    real dropdowns rather than a free-text box. Empty for the majority of templates, whose
    download URL is fixed or resolved by an update stage.
    """
    settings: list[SettingSpec] | None = None
    """
    The configurable settings exposed for this application (command-line args, config-file values, presentation)
    """
    config_file_mappings: Annotated[
        list[ConfigFileMapping] | None, Field(alias='configFileMappings')
    ] = None
    """
    How settings are read from and written back to the application's config files
    """
    events: list[EventSpec] | None = None
    """
    Events this application reports on its console, declared as regexes whose named capture
    groups become the event's parameters. They appear in the schedule editor's trigger picker
    beside AMP's own events and behave identically once fired.
    """
    backup_exclusions: Annotated[list[str] | None, Field(alias='backupExclusions')] = (
        None
    )
    """
                 Files this application produces that are worthless in a backup - logs, crash dumps,
                 caches. AMP 2 carried these in a `.backupExclude` file shipped inside the template's
                 data; declaring them here instead keeps the whole application definition in one document.

                 Used once, to seed a new shard's exclusion list (.amp/.usersnapshotignore) - after
    that the list is the user's, and the file manager's snapshot toggle edits it. Paths are
    relative to the app's base directory and use the same grammar as that file:
    logs/ for a folder and its subtree, *.log for a single-segment glob.
    """
    locale: dict[str, Any] | None = None
    """
    The template's own translations, keyed by language, in Transloco's own shape. Any
    user-facing string elsewhere in the spec may be a key into this table.
    """
    container_runtime_available: Annotated[
        bool | None, Field(alias='containerRuntimeAvailable')
    ] = None
    """
    Whether AMP has a container image it can run this app in. Not authored: the API sets it when
    a spec is served, from the live ContainerImageCatalog for whatever
    image this template names, and it is false only when that image is one of AMP's own that the
    image publisher has not built. A spec read from disk or the bus carries the default, true.

    Carried on the spec so the catalogue can grey the app out using the SAME table the
    launcher resolves against, rather than the browser keeping its own copy of which images
    exist. It is spire-independent on purpose - whether a missing image actually BLOCKS creation
    also depends on whether the app would be containerised on the chosen spire, which is the
    caller's half of the question (see ContainerModePolicy.CanCreate).
    """


