class EntryNodeSetupProgress(BaseModel):
    """
                 The bring-up of a public entry node, broken into the stages that fail for different reasons.

                 It exists because "it has not worked yet" was, for most of this process, the only thing either end
    could say. A tunnel that never forms, a bus that is not listening on the tunnel address, a join
    file nobody pasted and a firewall eating the setup port all present identically at the end of the
    chain - as a connection that does not happen - and each needs something completely different done
    about it. Naming the rungs is what lets an operator see WHERE it stopped instead of only that it
    did.The rungs are ordered, and each is only meaningful once the one before it is done. The two in the
    middle are the ones that earn the whole thing: string EntryNodeSetupProgress.TunnelConnected answers "is the wire
    up", and string EntryNodeSetupProgress.BusReachable answers "is anything listening at the other end of it". Those
    two failing look the same from a distance and have nothing in common up close.
    """

    model_config = ConfigDict(
        populate_by_name=True,
    )
    steps: list[EntryNodeSetupStep]
    """
    The ladder, in order
    """
    complete: bool
    """
    True once this machine is fully part of the installation
    """


class JobExecution(BaseModel):
    """
    Immutable record of one firing of a ScheduleDefinition.
    Stored in NATS KV at `amp.tn.{tenant}.job.{executionId}`.

    The NATS message that enqueued the firing uses a deterministic dedup ID
    (time triggers: `{scheduleId}.{canonicalFireTime unixMs}`; event triggers:
    `{scheduleId}.{EventId}`) so even if every node publishes, only one
    message enters the stream.
    """

    model_config = ConfigDict(
        populate_by_name=True,
    )
    id: UUID | None = None
    schedule_id: Annotated[UUID | None, Field(alias='scheduleId')] = None
    tenant_id: Annotated[str | None, Field(alias='tenantId')] = None
    shard_id: Annotated[UUID | None, Field(alias='shardId')] = None
    event_payload: Annotated[str | None, Field(alias='eventPayload')] = None
    """
    Raw event payload (JSON) for event-triggered runs; null for time triggers.
                The consumer maps it into run-context values via the TriggerCatalog schema
    """
    canonical_fire_time: Annotated[
        AwareDatetime | None, Field(alias='canonicalFireTime')
    ] = None
    """
    The canonical time this firing was *supposed* to occur.
    Part of the dedup ID for time triggers - deterministic across all nodes.
    """
    timeout: Annotated[
        str | None, Field(pattern='^-?(\\d+\\.)?\\d{2}:\\d{2}:\\d{2}(\\.\\d{1,7})?$')
    ] = None
    """
    Copied from the definition at publish so the worker can arm it without a lookup
    """
    queued_at: Annotated[AwareDatetime | None, Field(alias='queuedAt')] = None
    started_at: Annotated[AwareDatetime | None, Field(alias='startedAt')] = None
    completed_at: Annotated[AwareDatetime | None, Field(alias='completedAt')] = None
    status: JobStatus | None = None
    attempt_number: Annotated[int | None, Field(alias='attemptNumber')] = None
    worker_node: Annotated[str | None, Field(alias='workerNode')] = None
    """
    The node/worker that ran this execution
    """
    error_message: Annotated[str | None, Field(alias='errorMessage')] = None
    """
    Run-level failure summary (first unhandled error), for the trigger badge
    """
    step_outcomes: Annotated[list[StepOutcome] | None, Field(alias='stepOutcomes')] = (
        None
    )
    """
    Per-step results, keyed to the definition's step ids - the run journal
    """
    duration: Annotated[
        str | None, Field(pattern='^-?(\\d+\\.)?\\d{2}:\\d{2}:\\d{2}(\\.\\d{1,7})?$')
    ] = None


