class ScheduleDefinition(BaseModel):
    """
    Durable definition of a shard's scheduled behaviour, stored in NATS KV at
    `amp.tn.{tenant}.sched.{id}`: a trigger (when) plus a step TREE (what) -
    see Step. Executions are separate JobExecution records;
    live health is the separate ScheduleStatus key so frequent status
    writes never race user edits of the definition.
    """

    model_config = ConfigDict(
        populate_by_name=True,
    )
    id: UUID | None = None
    tenant_id: Annotated[str | None, Field(alias='tenantId')] = None
    shard_id: Annotated[UUID | None, Field(alias='shardId')] = None
    """
    The shard this schedule belongs to (v1: schedules are shard-scoped)
    """
    name: str | None = None
    description: str | None = None
    trigger: Trigger | None = None
    steps: list[Step] | None = None
    """
    The behaviour tree executed on each firing
    """
    retry_policy: Annotated[RetryPolicy | None, Field(alias='retryPolicy')] = None
    misfire_policy: Annotated[MisfirePolicy | None, Field(alias='misfirePolicy')] = None
    timeout: Annotated[
        str | None, Field(pattern='^-?(\\d+\\.)?\\d{2}:\\d{2}:\\d{2}(\\.\\d{1,7})?$')
    ] = None
    """
    Maximum wall-clock time allowed for a single execution (all lanes) before it is
    considered timed out.
    """
    enabled: bool | None = None
    created_at: Annotated[AwareDatetime | None, Field(alias='createdAt')] = None
    updated_at: Annotated[AwareDatetime | None, Field(alias='updatedAt')] = None
    created_by_user_id: Annotated[str | None, Field(alias='createdByUserId')] = None
    """
    Who originally created the schedule (audit/display only)
    """
    run_as_user_id: Annotated[str | None, Field(alias='runAsUserId')] = None
    """
    The identity the schedule ACTS AS: its steps execute under this user's LIVE permissions,
    so a schedule can never perform something its author couldn't do directly. Set to the
    user on every create AND update (the last editor authors what runs, so editing someone
    else's schedule can't be an escalation path). A missing value fails guarded actions closed.
    """


